    """Sample all edges of G(n,p) in O(n^2) time."""
    if n < 1 or not 0.0 <= p <= 1.0:
        raise ValueError("require n >= 1 and 0 <= p <= 1")
    return {
        (u, v)
        for u in range(n)
        for v in range(u + 1, n)
